/// First line of a journal file.
#[derive(serde::Serialize, serde::Deserialize, Debug, PartialEq, Eq)]
pub struct JournalHeader {
    pub format_version: u32,
    pub path: String,
}

#[derive(serde::Serialize, serde::Deserialize, Debug, PartialEq, Eq)]
pub struct JournalEdit {
    pub start: usize,
    pub old: String,
    pub new: String,
}

/// One applied transaction.
#[derive(serde::Serialize, serde::Deserialize, Debug, PartialEq, Eq)]
pub struct JournalLine {
    pub revision_before: u64,
    pub revision_after: u64,
    pub edits: Vec<JournalEdit>,
}

pub fn header_line(path: &std::path::Path) -> String
/// One JSON object on one line for the forward transaction of `entry`.
pub fn journal_line(entry: &kate_text::HistoryEntry) -> String
pub fn journal_line_from_str(text: &str) -> Option<JournalLine>
/// `home/Library/Application Support/KateM5Rust/recovery`.
pub fn recovery_dir(home: &std::path::Path) -> std::path::PathBuf
/// `dir/<hex digest>.jsonl`.
pub fn journal_path(dir: &std::path::Path, digest: &[u8; 32]) -> std::path::PathBuf
